DECLARE
 payload JSONB := $payload${"en": {"project": {"id": "ivr-studio", "title": "ivr-studio - Vietnamese Speech Synthesis", "role": "Creator / Maintainer", "category": "Applied AI", "focus": "speech-ai", "summary": "Turn Vietnamese scripts into IVR audio with text-to-speech and reference-conditioned voice generation. Includes per-line preview, regeneration, and MP3/WAV export.", "description": "Built a local web application and CLI for producing Vietnamese interactive voice response (IVR) greetings and menus from text. Integrated edge-tts for standard voices and a pretrained F5-TTS model for reference-conditioned, zero-shot speech generation; no model training or fine-tuning is performed by this project.\n\nA Node.js server orchestrates Python inference and FFmpeg audio processing. A resident Python worker reuses the loaded F5-TTS checkpoint across requests and releases it after inactivity. The pipeline normalizes Vietnamese numbers, splits long text into model-safe chunks, controls timing, and assembles MP3/WAV output.\n\nOptional Whisper transcription checks generated speech against the script, triggering bounded retries and retaining the best-matching result. Users can preview and regenerate individual lines, review reference transcripts, and reopen saved jobs through the web interface.\n\nThis is a local prototype for model integration and audio workflow engineering. The selected Vietnamese F5-TTS checkpoint has non-commercial restrictions; reference voices require appropriate usage rights. It is not presented as a commercially cleared voice service.", "tech": ["Node.js", "Python", "F5-TTS", "edge-tts", "Whisper.cpp", "FFmpeg", "PyTorch / MPS", "Server-Sent Events"], "highlights": ["Built a Node.js web application integrating edge-tts and pretrained F5-TTS for Vietnamese text-to-speech and reference-conditioned voice generation; orchestrated Python inference without training a new model.", "Implemented a resident Python model worker, Vietnamese number normalization, text chunking, and FFmpeg audio assembly with per-line preview and MP3/WAV export.", "Added optional Whisper-based transcript verification, bounded regeneration retries, and manual per-line review to address missing words and speech-generation variability."], "featured": true, "links": [{"id": "source", "type": "github", "url": "https://github.com/sdc-ren/ivr-studio", "label": "", "showInCv": true}], "images": [], "coverImageId": ""}, "skill": {"id": "speech-ai", "name": "Speech AI & Model Integration", "items": ["Text-to-speech (TTS)", "Pretrained F5-TTS inference", "Reference-conditioned generation", "Whisper transcription verification", "FFmpeg audio pipelines", "Resident model workers"]}, "focus": {"localmem": "ai-agent-memory", "gdrive-cli": "ai-agent-tooling", "cc-notify-telegram": "ai-workflow", "altfins": "workflow-automation"}}, "vi": {"project": {"id": "ivr-studio", "title": "ivr-studio - Vietnamese Speech Synthesis", "role": "Creator / Maintainer", "category": "Applied AI", "focus": "speech-ai", "summary": "Chuyển kịch bản tiếng Việt thành audio IVR bằng text-to-speech và sinh giọng theo mẫu tham chiếu. Có nghe thử, sinh lại từng dòng và xuất MP3/WAV.", "description": "Ứng dụng web cục bộ và CLI tạo lời chào/menu IVR tiếng Việt. Tích hợp edge-tts và mô hình F5-TTS có sẵn để sinh giọng zero-shot theo clip tham chiếu; dự án không huấn luyện hoặc fine-tune model.\n\nNode.js điều phối Python inference và FFmpeg. Worker Python thường trực giữ model giữa các yêu cầu và giải phóng khi rảnh; pipeline chuẩn hóa số tiếng Việt, chia đoạn văn bản và ghép MP3/WAV.\n\nTùy chọn dùng Whisper kiểm tra lời đọc, thử sinh lại có giới hạn và giữ bản khớp nhất. Người dùng nghe thử, sinh lại từng dòng, duyệt transcript và mở lại job đã lưu.\n\nĐây là prototype cục bộ về tích hợp model và workflow âm thanh. Checkpoint F5-TTS tiếng Việt có giới hạn phi thương mại; giọng tham chiếu cần quyền sử dụng phù hợp, không được mô tả là dịch vụ giọng nói đã sẵn sàng thương mại.", "tech": ["Node.js", "Python", "F5-TTS", "edge-tts", "Whisper.cpp", "FFmpeg", "PyTorch / MPS", "Server-Sent Events"], "highlights": ["Xây dựng web app Node.js tích hợp edge-tts và F5-TTS có sẵn cho TTS tiếng Việt/sinh giọng theo mẫu; điều phối Python inference, không huấn luyện model mới.", "Triển khai worker Python thường trực, chuẩn hóa số, chia văn bản và ghép audio bằng FFmpeg; hỗ trợ nghe từng dòng và xuất MP3/WAV.", "Tùy chọn kiểm tra transcript bằng Whisper, thử sinh lại có giới hạn và duyệt từng dòng để xử lý nuốt chữ và tính ngẫu nhiên của model."], "featured": true, "links": [{"id": "source", "type": "github", "url": "https://github.com/sdc-ren/ivr-studio", "label": "", "showInCv": true}], "images": [], "coverImageId": ""}, "skill": {"id": "speech-ai", "name": "Speech AI & Model Integration", "items": ["Text-to-speech (TTS)", "Pretrained F5-TTS inference", "Reference-conditioned generation", "Whisper transcription verification", "FFmpeg audio pipelines", "Resident model workers"]}, "focus": {"localmem": "ai-agent-memory", "gdrive-cli": "ai-agent-tooling", "cc-notify-telegram": "ai-workflow", "altfins": "workflow-automation"}}, "patches": {"en": [{"collection": "cvs", "id": "ai-engineer", "field": "summary", "before": "Software Engineer with 12 years of web development experience, including around six years of frontend technical leadership, focused on AI agent engineering and workflow automation. Built Model Context Protocol (MCP) servers, local memory retrieval, Google Workspace tools, and human-in-the-loop coding-assistant integrations using Python and Node.js. Hands-on work covers tool schemas, context management, retrieval evaluation, API integration, and automated testing; current research includes prompt engineering and multi-agent workflows.", "after": "Software Engineer with 12 years of web development experience, including around six years of frontend technical leadership, focused on AI agent engineering and applied model integration. Built MCP servers, local memory retrieval, human-in-the-loop coding workflows, and Vietnamese speech synthesis using pretrained F5-TTS, Python, and Node.js. Hands-on work covers context management, retrieval evaluation, inference-worker orchestration, API integration, and automated testing; current research includes prompt engineering and multi-agent workflows."}, {"collection": "cvs", "id": "ai-engineer", "field": "projectIds", "before": ["localmem", "gdrive-cli", "cc-notify-telegram", "altfins"], "after": ["localmem", "ivr-studio", "gdrive-cli", "cc-notify-telegram"]}, {"collection": "cvs", "id": "ai-engineer", "field": "skillIds", "before": ["ai-engineering", "ai-programming", "ai-reliability", "ai-development-tools", "architecture", "devops-delivery"], "after": ["ai-engineering", "ai-programming", "ai-reliability", "speech-ai", "ai-development-tools", "devops-delivery"]}, {"collection": "projects", "id": "gdrive-cli", "field": "summary", "before": "Built Google Workspace CLI/MCP tools that let AI coding agents read scoped test cases and documents, update data, and automate workflows using service-account permissions.", "after": "Connect AI coding agents to Google Drive, Sheets, Docs, and Slides for test-case retrieval and data-entry workflows. Service-account scope and filtered reads keep access and context focused."}, {"collection": "projects", "id": "cc-notify-telegram", "field": "summary", "before": "Built a Telegram bridge for AI coding assistants so users can receive alerts, answer questions, and approve pending requests without continuously monitoring their computer.", "after": "Step away while AI coding assistants work: receive completion alerts, answer questions, and approve pending requests through Telegram. Replies return to the originating session."}, {"collection": "projects", "id": "altfins", "field": "summary", "before": "Built a Python/Playwright data pipeline that runs 24/7, normalizes cryptocurrency analysis with Pydantic, stores records in Supabase, and sends deduplicated Telegram alerts.", "after": "Monitor cryptocurrency analysis without repeatedly visiting source pages. A scheduled Python pipeline stores structured data and sends deduplicated Telegram alerts."}, {"collection": "projects", "id": "localmem", "field": "summary", "before": "Built persistent memory for AI coding agents with Python, SQLite FTS5/BM25, and MCP, enabling local retrieval across sessions without LLM calls on the recall path.", "after": "Persistent memory for AI coding agents across sessions and projects. Local SQLite/FTS5 retrieval through MCP recalls relevant context without LLM calls on the retrieval path."}], "vi": [{"collection": "cvs", "id": "ai-engineer", "field": "summary", "before": "Kỹ sư phần mềm với 12 năm phát triển web, trong đó khoảng 6 năm dẫn dắt kỹ thuật frontend, tập trung vào AI agent tooling và tự động hóa workflow. Xây dựng bộ nhớ truy hồi cục bộ, công cụ CLI/MCP cho Google Workspace và hooks gửi thông báo, yêu cầu phê duyệt qua Telegram. Kết hợp Python/TypeScript, tích hợp API và kiểm thử tự động với nghiên cứu prompt engineering và workflow đa agent.", "after": "Kỹ sư phần mềm với 12 năm phát triển web, trong đó khoảng 6 năm dẫn dắt kỹ thuật frontend, tập trung vào AI agent engineering và tích hợp model. Xây dựng MCP servers, bộ nhớ truy hồi cục bộ, workflow có người phê duyệt và tổng hợp giọng tiếng Việt bằng F5-TTS có sẵn, Python và Node.js. Kinh nghiệm thực tế gồm context management, đánh giá truy hồi, điều phối inference worker, tích hợp API và kiểm thử; đang nghiên cứu prompt engineering và workflow đa agent."}, {"collection": "cvs", "id": "ai-engineer", "field": "projectIds", "before": ["localmem", "gdrive-cli", "cc-notify-telegram", "altfins"], "after": ["localmem", "ivr-studio", "gdrive-cli", "cc-notify-telegram"]}, {"collection": "cvs", "id": "ai-engineer", "field": "skillIds", "before": ["ai-engineering", "ai-programming", "ai-reliability", "ai-development-tools", "architecture", "devops-delivery"], "after": ["ai-engineering", "ai-programming", "ai-reliability", "speech-ai", "ai-development-tools", "devops-delivery"]}]}}$payload$::jsonb;
 entry RECORD; snapshot TEXT; document JSONB; addition JSONB; item JSONB;
 patch JSONB; collection TEXT; project_index INTEGER; target TEXT[];
 next_draft JSONB; next_published JSONB; project_id TEXT; focus_value JSONB;
BEGIN
 FOR entry IN SELECT * FROM "Content" WHERE "locale" IN ('en','vi') FOR UPDATE LOOP
  next_draft := entry."draft"; next_published := entry."published";
  addition := payload->entry."locale";
  FOREACH snapshot IN ARRAY ARRAY['draft','published'] LOOP
   document := CASE WHEN snapshot='draft' THEN next_draft ELSE next_published END;
   IF document IS NULL OR document='null'::jsonb THEN CONTINUE; END IF;
   FOREACH collection IN ARRAY ARRAY['projects','skills'] LOOP
    item := CASE WHEN collection='projects' THEN addition->'project' ELSE addition->'skill' END;
    IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(document->collection,'[]'::jsonb)) e WHERE e->>'id'=item->>'id') THEN
     document := jsonb_set(document,ARRAY[collection],COALESCE(document->collection,'[]'::jsonb)||jsonb_build_array(item),true);
    END IF;
   END LOOP;
   FOR project_id,focus_value IN SELECT key,value FROM jsonb_each(addition->'focus') LOOP
    SELECT (ordinality-1)::INTEGER INTO project_index FROM jsonb_array_elements(COALESCE(document->'projects','[]'::jsonb)) WITH ORDINALITY
     WHERE value->>'id'=project_id LIMIT 1;
    IF project_index IS NOT NULL AND (document #> ARRAY['projects',project_index::TEXT,'focus']) IS NULL THEN
     document := jsonb_set(document,ARRAY['projects',project_index::TEXT,'focus'],focus_value,true);
    END IF;
   END LOOP;
   FOR item IN SELECT value FROM jsonb_array_elements(addition->'project'->'tech') LOOP
    IF NOT COALESCE(document->'technologies','[]'::jsonb) @> jsonb_build_array(item) THEN
     document := jsonb_set(document,'{technologies}',COALESCE(document->'technologies','[]'::jsonb)||jsonb_build_array(item),true);
    END IF;
   END LOOP;
   FOR patch IN SELECT value FROM jsonb_array_elements(payload->'patches'->entry."locale") LOOP
    SELECT (ordinality-1)::INTEGER INTO project_index FROM jsonb_array_elements(COALESCE(document->(patch->>'collection'),'[]'::jsonb)) WITH ORDINALITY
     WHERE value->>'id'=patch->>'id' LIMIT 1;
    IF project_index IS NULL THEN CONTINUE; END IF;
    target := ARRAY[patch->>'collection',project_index::TEXT,patch->>'field'];
    IF document #> target = patch->'before' THEN document := jsonb_set(document,target,patch->'after',false); END IF;
   END LOOP;
   IF snapshot='draft' THEN next_draft:=document; ELSE next_published:=document; END IF;
  END LOOP;
  IF next_draft IS DISTINCT FROM entry."draft" OR next_published IS DISTINCT FROM entry."published" THEN
   UPDATE "Content" SET "draft"=next_draft,"published"=next_published,"revision"="revision"+1,"updatedAt"=CURRENT_TIMESTAMP,
    "publishedAt"=CASE WHEN next_published IS DISTINCT FROM entry."published" THEN CURRENT_TIMESTAMP ELSE entry."publishedAt" END
    WHERE "locale"=entry."locale";
  END IF;
 END LOOP;
END $migration$;
